<h1>Yönetim paneli</h1>
<section class="card"><h2>Genel ve banka ayarları</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="settings"><label>Site adı</label><input name="site_name" value="<?=e($settings['site_name']??'SMM Panel')?>"><label>Banka</label><input name="bank_name" value="<?=e($settings['bank_name']??'')?>"><label>IBAN</label><input name="bank_iban" value="<?=e($settings['bank_iban']??'')?>"><label>Hesap sahibi</label><input name="bank_account_name" value="<?=e($settings['bank_account_name']??'')?>"><button>Ayarları kaydet</button></form></section>
<section class="card"><h2>Bekleyen bakiye bildirimleri</h2><?php if(!$topups):?><p>Bekleyen bildirim yok.</p><?php endif?><?php foreach($topups as $t):?><form method="post" class="line"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="topup"><input type="hidden" name="id" value="<?=$t['id']?>"><?=e($t['email'])?> · <?=money($t['amount'])?> · <?=e($t['note'])?><button name="decision" value="approve">Onayla</button><button class="danger" name="decision" value="reject">Reddet</button></form><?php endforeach?></section>
<section class="card"><h2>API sağlayıcıları</h2><p>Standart SMM Panel API protokolü desteklenir. Anahtarlar şifreli saklanır.</p><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="provider_save"><label>Sağlayıcı adı</label><input name="name" required><label>API URL (HTTPS)</label><input name="api_url" type="url" placeholder="https://provider.example/api/v2" required><label>API anahtarı</label><input name="api_key" type="password" required><button>Sağlayıcı ekle</button></form><?php foreach($providers as $p):?><div class="line"><b><?=e($p['name'])?></b> · <?=e($p['status'])?><small><?=e($p['api_url'])?></small><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="action" value="provider_test">API bağlantısını test et</button><button class="secondary" name="action" value="provider_toggle">Aktif/Pasif</button></form><details><summary>Bilgileri güncelle</summary><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="provider_save"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Ad</label><input name="name" value="<?=e($p['name'])?>" required><label>API URL</label><input name="api_url" value="<?=e($p['api_url'])?>" required><label>Yeni API anahtarı (boş bırakılırsa korunur)</label><input name="api_key" type="password"><button>Güncelle</button></form></details></div><?php endforeach?></section>
<section class="card"><h2>Hizmet yönetimi</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="service_save"><label>Kategori</label><input name="category" required><label>Hizmet adı</label><input name="name" required><label>Açıklama</label><input name="description"><label>Satış fiyatı / 1000</label><input name="price_per_1000" type="number" min=".01" step=".0001" required><label>Minimum miktar</label><input name="min_qty" type="number" min="1" value="100" required><label>Maksimum miktar</label><input name="max_qty" type="number" min="1" value="100000" required><label>Sağlayıcı</label><select name="provider_id"><option value="0">Manuel işlem / sağlayıcı yok</option><?php foreach($providers as $p):if($p['status']==='active'):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endif;endforeach?></select><label>Sağlayıcı servis ID</label><input name="provider_service_id"><button>Hizmet ekle</button></form><?php foreach($services as $s):?><div class="line"><b><?=e($s['category'])?> / <?=e($s['name'])?></b> · <?=money($s['price_per_1000'])?> / 1000 · <?=!empty($s['provider_name'])?e($s['provider_name']):'Manuel'?><small><?=e($s['description'])?> · <?=$s['min_qty']?>–<?=$s['max_qty']?> · <?=((int)$s['active']===1)?'Aktif':'Pasif'?></small><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="service_toggle"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="secondary">Aktif/Pasif</button></form></div><?php endforeach?></section>
<section class="card"><h2>Sipariş yönetimi</h2><?php foreach($orders as $o):?><div class="line">#<?=$o['id']?> · <?=e($o['email'])?> · <?=e($o['service'])?> · <?=$o['quantity']?> · <?=money($o['charge'])?> · <b><?=e($o['status'])?></b><?php if($o['provider_order_id']):?> · API #<?=e($o['provider_order_id'])?><?php endif?><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="order_status"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status"><?php foreach(['manual_review','queued','processing','completed','partial','canceled','failed'] as $st):?><option value="<?=$st?>" <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach?></select><button>Durumu kaydet</button></form></div><?php endforeach?></section>
<section class="card"><h2>Kullanıcı yönetimi</h2><?php foreach($users as $u):?><div class="line"><?=e($u['name'])?> · <?=e($u['email'])?> · <?=e($u['role'])?> · <?=e($u['status'])?> · <?=money($u['balance'])?><?php if($u['role']==='user'):?><form method="post"><input type="hidden" name="_csrf" value="<?=e($_SESSION['_csrf']??'')?>"><input type="hidden" name="action" value="user_toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="secondary">Aktif/Pasif</button></form><?php endif?></div><?php endforeach?></section>
<section class="card"><h2>Sağlayıcı işlem kayıtları</h2><?php if(!$logs):?><p>Henüz kayıt yok.</p><?php endif?><?php foreach($logs as $l):?><p><small><?=e($l['created_at'])?></small> · <?=e($l['level'])?> · <?=e($l['provider_name']??'Sistem')?> · <?=e($l['message'])?></p><?php endforeach?></section>